def solve_case(p, r):
    # We search for the largest prime q such that p < q < r

    # Start q search from the largest prime less than r
    q = r - 1
    while q > p:
        if is_prime(q):
            # Check conditions using p+r=800
            # P1 = 2p + q - 800
            # P2 = q + 800 - 2p
            # P3 = 800 - q
            # P4 = q + 800

            P1 = 2 * p + q - 800
            P2 = q + 800 - 2 * p
            P3 = 800 - q
            P4 = q + 800

            if is_prime(P1) and is_prime(P2) and is_prime(P3) and is_prime(P4):
                # Found the largest valid q for this (p, r) pair
                return q

        # Move to the next smaller number
        q -= 1
    return None

